package vn.cineman.dao;
import java.sql.*;import java.util.*;
public class CinemaDao8 {
 public List<Map<String,Object>> movies(Connection c,String q)throws SQLException{return Db8.query(c,"SELECT * FROM movies WHERE title LIKE ? OR genre LIKE ? ORDER BY id DESC","%"+q+"%","%"+q+"%");}
 public List<Map<String,Object>> rooms(Connection c)throws SQLException{return Db8.query(c,"SELECT * FROM rooms ORDER BY id");}
 public List<Map<String,Object>> shows(Connection c)throws SQLException{return Db8.query(c,"SELECT s.*,m.title,r.name room FROM shows s JOIN movies m ON m.id=s.movie_id JOIN rooms r ON r.id=s.room_id WHERE s.starts_at>NOW() ORDER BY s.starts_at");}
 public List<Map<String,Object>> seats(Connection c,long id)throws SQLException{return Db8.query(c,"SELECT se.*,CAST(SUBSTRING(se.label,2)='1' AS UNSIGNED) row_start,CAST(EXISTS(SELECT 1 FROM tickets t WHERE t.show_id=? AND t.seat_id=se.id) AS UNSIGNED) sold, CAST(EXISTS(SELECT 1 FROM seat_holds h WHERE h.show_id=? AND h.seat_id=se.id AND h.expires_at>NOW()) AS UNSIGNED) held FROM seats se JOIN shows s ON s.room_id=se.room_id WHERE s.id=? ORDER BY se.id",id,id,id);}
 public List<Map<String,Object>> users(Connection c,String q)throws SQLException{return Db8.query(c,"SELECT u.id,u.name,u.email,m.code FROM users u LEFT JOIN members m ON m.user_id=u.id WHERE u.role='CUSTOMER' AND (u.name LIKE ? OR u.email LIKE ?) ORDER BY u.id","%"+q+"%","%"+q+"%");}
 public Map<String,Object> login(Connection c,String email)throws SQLException{return first(Db8.query(c,"SELECT * FROM users WHERE email=?",email));}
 public Map<String,Object> customerContact(Connection c,long user)throws SQLException{return first(Db8.query(c,"SELECT id,name,email,phone FROM users WHERE id=? AND role='CUSTOMER'",user));}
 public void customerPhone(Connection c,long user,String phone)throws SQLException{Db8.update(c,"UPDATE users SET phone=? WHERE id=? AND role='CUSTOMER'",phone,user);}
 public void register(Connection c,String name,String email,String hash)throws SQLException{Db8.update(c,"INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'CUSTOMER')",name,email,hash);}
 public void card(Connection c,long user,String code)throws SQLException{Db8.update(c,"INSERT INTO members(user_id,code) SELECT id,? FROM users WHERE id=? AND role='CUSTOMER' ON DUPLICATE KEY UPDATE user_id=members.user_id",code,user);}
 public Map<String,Object> member(Connection c,String code)throws SQLException{return first(Db8.query(c,"SELECT * FROM members WHERE code=?",code));}
 public Map<String,Object> movie(Connection c,long id)throws SQLException{return first(Db8.query(c,"SELECT * FROM movies WHERE id=? FOR UPDATE",id));}
 public Map<String,Object> room(Connection c,long id)throws SQLException{return first(Db8.query(c,"SELECT * FROM rooms WHERE id=? FOR UPDATE",id));}
 public boolean referenced(Connection c,String type,long id)throws SQLException{return !Db8.query(c,type.equals("movie")?"SELECT id FROM shows WHERE movie_id=? LIMIT 1":"SELECT id FROM shows WHERE room_id=? LIMIT 1",id).isEmpty();}
 public void movieSave(Connection c,long id,String title,String genre,int duration,String description)throws SQLException{if(id==0)Db8.update(c,"INSERT INTO movies(title,genre,duration,description) VALUES(?,?,?,?)",title,genre,duration,description);else Db8.update(c,"UPDATE movies SET title=?,genre=?,duration=?,description=? WHERE id=?",title,genre,duration,description,id);}
 public void roomSave(Connection c,long id,String name,int rows,int cols)throws SQLException{if(id==0)id=Db8.update(c,"INSERT INTO rooms(name,seat_rows,seat_cols) VALUES(?,?,?)",name,rows,cols);else {Db8.update(c,"UPDATE rooms SET name=?,seat_rows=?,seat_cols=? WHERE id=?",name,rows,cols,id);Db8.update(c,"DELETE FROM seats WHERE room_id=?",id);}for(int a=0;a<rows;a++)for(int b=1;b<=cols;b++)Db8.update(c,"INSERT INTO seats(room_id,label) VALUES(?,?)",id,""+(char)('A'+a)+b);}
 public void delete(Connection c,String type,long id)throws SQLException{if(type.equals("room")){Db8.update(c,"DELETE FROM seats WHERE room_id=?",id);Db8.update(c,"DELETE FROM rooms WHERE id=?",id);}else Db8.update(c,"DELETE FROM movies WHERE id=?",id);}
 public boolean overlap(Connection c,long room,Timestamp start,Timestamp end)throws SQLException{return !Db8.query(c,"SELECT id FROM shows WHERE room_id=? AND starts_at<? AND ends_at>?",room,end,start).isEmpty();}
 public void schedule(Connection c,long movie,long room,Timestamp start,Timestamp end,java.math.BigDecimal price)throws SQLException{Db8.update(c,"INSERT INTO shows(movie_id,room_id,starts_at,ends_at,price) VALUES(?,?,?,?,?)",movie,room,start,end,price);}
 public Map<String,Object> show(Connection c,long id)throws SQLException{return first(Db8.query(c,"SELECT s.*,r.name room FROM shows s JOIN rooms r ON r.id=s.room_id WHERE s.id=? FOR UPDATE",id));}
 public Map<String,Object> existing(Connection c,String key)throws SQLException{return first(Db8.query(c,"SELECT * FROM orders WHERE request_key=?",key));}
 public boolean seatAvailable(Connection c,long show,long room,long seat)throws SQLException{return !Db8.query(c,"SELECT id FROM seats WHERE id=? AND room_id=? AND NOT EXISTS(SELECT 1 FROM tickets WHERE show_id=? AND seat_id=?) AND NOT EXISTS(SELECT 1 FROM seat_holds WHERE show_id=? AND seat_id=? AND expires_at>NOW())",seat,room,show,seat,show,seat).isEmpty();}
 public long order(Connection c,long actor,Long customer,String key,String channel,java.math.BigDecimal total)throws SQLException{return Db8.update(c,"INSERT INTO orders(actor_id,customer_id,request_key,channel,total) VALUES(?,?,?,?,?)",actor,customer,key,channel,total);}
 public long onlineOrder(Connection c,long actor,String key,java.math.BigDecimal total,String name,String email,String phone)throws SQLException{return Db8.update(c,"INSERT INTO orders(actor_id,customer_id,request_key,channel,total,contact_name,contact_email,contact_phone) VALUES(?,?,?,'ONLINE',?,?,?,?)",actor,actor,key,total,name,email,phone);}
 public void ticket(Connection c,long order,long show,long seat,java.math.BigDecimal price)throws SQLException{Db8.update(c,"INSERT INTO tickets(order_id,show_id,seat_id,price) VALUES(?,?,?,?)",order,show,seat,price);}
 public void payment(Connection c,long order,String method,java.math.BigDecimal total)throws SQLException{Db8.update(c,"INSERT INTO payments(order_id,method,amount) VALUES(?,?,?)",order,method,total);}
 public List<Map<String,Object>> orders(Connection c,long actor,boolean staff)throws SQLException{
  String sql="SELECT o.*,COALESCE(o.show_id,(SELECT t.show_id FROM tickets t WHERE t.order_id=o.id LIMIT 1)) AS show_id,COALESCE(s.movie_id,(SELECT s2.movie_id FROM tickets t2 JOIN shows s2 ON s2.id=t2.show_id WHERE t2.order_id=o.id LIMIT 1)) AS movie_id,COALESCE(s.starts_at,(SELECT s3.starts_at FROM tickets t3 JOIN shows s3 ON s3.id=t3.show_id WHERE t3.order_id=o.id LIMIT 1)) AS starts_at,COALESCE(m.title,(SELECT m4.title FROM tickets t4 JOIN shows s4 ON s4.id=t4.show_id JOIN movies m4 ON m4.id=s4.movie_id WHERE t4.order_id=o.id LIMIT 1)) AS movie_title,COALESCE(r.name,(SELECT r5.name FROM tickets t5 JOIN shows s5 ON s5.id=t5.show_id JOIN rooms r5 ON r5.id=s5.room_id WHERE t5.order_id=o.id LIMIT 1)) AS room_name,COALESCE((SELECT GROUP_CONCAT(se.label ORDER BY se.label SEPARATOR ', ') FROM order_seats os JOIN seats se ON se.id=os.seat_id WHERE os.order_id=o.id),(SELECT GROUP_CONCAT(se2.label ORDER BY se2.label SEPARATOR ', ') FROM tickets t6 JOIN seats se2 ON se2.id=t6.seat_id WHERE t6.order_id=o.id)) AS seat_labels FROM orders o LEFT JOIN shows s ON s.id=o.show_id LEFT JOIN movies m ON m.id=s.movie_id LEFT JOIN rooms r ON r.id=s.room_id WHERE (? OR o.actor_id=?) ORDER BY o.id DESC";
  return Db8.query(c,sql,staff,actor);
 }
 public Map<String,Object> receipt(Connection c,long id)throws SQLException{
  String sql="SELECT o.*,u.name cashier,COALESCE(o.show_id,(SELECT t.show_id FROM tickets t WHERE t.order_id=o.id LIMIT 1)) AS show_id,COALESCE(s.movie_id,(SELECT s2.movie_id FROM tickets t2 JOIN shows s2 ON s2.id=t2.show_id WHERE t2.order_id=o.id LIMIT 1)) AS movie_id,COALESCE(s.starts_at,(SELECT s3.starts_at FROM tickets t3 JOIN shows s3 ON s3.id=t3.show_id WHERE t3.order_id=o.id LIMIT 1)) AS starts_at,COALESCE(m.title,(SELECT m4.title FROM tickets t4 JOIN shows s4 ON s4.id=t4.show_id JOIN movies m4 ON m4.id=s4.movie_id WHERE t4.order_id=o.id LIMIT 1)) AS movie_title,COALESCE(r.name,(SELECT r5.name FROM tickets t5 JOIN shows s5 ON s5.id=t5.show_id JOIN rooms r5 ON r5.id=s5.room_id WHERE t5.order_id=o.id LIMIT 1)) AS room_name FROM orders o JOIN users u ON u.id=o.actor_id LEFT JOIN shows s ON s.id=o.show_id LEFT JOIN movies m ON m.id=s.movie_id LEFT JOIN rooms r ON r.id=s.room_id WHERE o.id=?";
  return first(Db8.query(c,sql,id));
 }
 public List<Map<String,Object>> tickets(Connection c,long order)throws SQLException{return Db8.query(c,"SELECT t.id,t.price,m.title,s.starts_at,se.label,r.name room FROM tickets t JOIN shows s ON s.id=t.show_id JOIN movies m ON m.id=s.movie_id JOIN seats se ON se.id=t.seat_id JOIN rooms r ON r.id=s.room_id WHERE t.order_id=?",order);}
 public List<Map<String,Object>> stats(Connection c,String type,java.sql.Date from,java.sql.Date to)throws SQLException {String sql=switch(type){case "movies"->"SELECT m.title label,COUNT(*) tickets,SUM(t.price) revenue FROM tickets t JOIN orders o ON o.id=t.order_id JOIN shows s ON s.id=t.show_id JOIN movies m ON m.id=s.movie_id WHERE o.created_at>=? AND o.created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY m.id,m.title";case "customers"->"SELECT u.name label,COUNT(DISTINCT o.id) purchases,COUNT(*) tickets,SUM(t.price) revenue FROM orders o JOIN users u ON u.id=o.customer_id JOIN tickets t ON t.order_id=o.id WHERE o.created_at>=? AND o.created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY u.id,u.name";default->"SELECT CONCAT(day,' / ',channel) label,purchases,revenue FROM (SELECT DATE(created_at) day,channel,COUNT(*) purchases,SUM(total) revenue FROM orders WHERE status='PAID' AND created_at>=? AND created_at<DATE_ADD(?,INTERVAL 1 DAY) GROUP BY DATE(created_at),channel) daily ORDER BY day";};return Db8.query(c,sql,from,to);}
 public static Map<String,Object> first(List<Map<String,Object>> rows){return rows.isEmpty()?null:rows.get(0);}
}
